import{_ as r,a0 as p,w as l,s,ao as u,I as i,x as t,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux用户，你们真的了解开源硬件吗？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux用户，你们真的了解开源硬件吗？ | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux用户，你们真的了解开源硬件吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux用户，你们真的了解开源硬件吗？ | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20140929 What Linux Users Should Know About Open Hardware","title":"Linux用户，你们真的了解开源硬件吗？","tag":"201501","desc":""},"relativePath":"201501/20140929 What Linux Users Should Know About Open Hardware.md","filePath":"[post].md"}'),d={name:"201501/20140929 What Linux Users Should Know About Open Hardware.md"};function h(m,a,x,f,L,w){const e=p("Link");return l(),s("div",null,[a[13]||(a[13]=u('<h1 id="linux用户-你们真的了解开源硬件吗" tabindex="-1">Linux用户，你们真的了解开源硬件吗？ <a class="header-anchor" href="#linux用户-你们真的了解开源硬件吗" aria-label="Permalink to “Linux用户，你们真的了解开源硬件吗？”">​</a></h1><blockquote><p>Linux用户不了解一点开源硬件制造相关的事情，他们就会经常陷入失望的情绪中。</p></blockquote><p>商业软件和免费软件已经互相纠缠很多年了，但是这俩经常误解对方。这并不奇怪 -- 对一方来说是生意，而另一方只是一种生活方式。但是，这种误解会给人带来痛苦，这也是为什么值得花精力去揭露这里面的内幕。</p><p>一个逐渐普遍的现象：对开源硬件的不断尝试，不管是Canonical，Jolla，MakePlayLive，或者其他公司。无论是评论员或是终端用户，通常免费软件用户都会为新的硬件平台发布表现出过分的狂热，然后因为不断延期有所醒悟，直到最终放弃整个产品。</p><p>这是一个没有人获益的怪圈，而且常常滋生出不信任 - 都是因为一般的Linux用户根本不知道这些新闻背后发生的事情。</p><p>我个人对于把产品推向市场的经验很有限。但是，我还没听说谁能有所突破。推出一个开源硬件或其他产品到市场仍然不仅仅是个残酷的生意，而且严重不利于新进厂商。</p><h3 id="寻找合作伙伴" tabindex="-1">寻找合作伙伴 <a class="header-anchor" href="#寻找合作伙伴" aria-label="Permalink to “寻找合作伙伴”">​</a></h3><p>不管是数码产品的生产还是分销都被相对较少的一些公司控制着，有时需要数月的预订。利润率也会很低，所以就像那些购买古老情景喜剧的电影工作室一样，生产商一般也希望复制当前热销产品的成功。像Aaron Seigo在谈到他花精力开发Vivaldi平板时告诉我的，生产商更希望能由其他人去承担开发新产品的风险。</p><p>不仅如此，他们更希望和那些有现成销售记录的有可能带来长期客户生意的人合作。</p><p>而且，一般新加入的厂商所关心的产品只有几千的量。芯片制造商更愿意和苹果或三星这样的公司合作，因为它们的订单很可能是几十上百万的量。</p><p>面对这种情形，开源硬件制造者们可能会发现他们在工厂的列表中被淹没了，除非能找到二线或三线厂愿意尝试一下小批量生产新产品。</p><p>他们也许还会沦为采购成品组件再自己组装，就像Seigo尝试Vivaldi时那样做的。或者，他们也许可以像Canonical那样做，寻找一些愿意为这个产业冒险的合作伙伴。而就算他们成功了，一般也会比最初天真的预期延迟数个月。</p><h3 id="磕磕碰碰走向市场" tabindex="-1">磕磕碰碰走向市场 <a class="header-anchor" href="#磕磕碰碰走向市场" aria-label="Permalink to “磕磕碰碰走向市场”">​</a></h3><p>然而，寻找生产商只是第一关。根据树莓派项目的经验，就算开源硬件制造者们只想在他们的产品上运行免费软件，生产商们很可能会以保护商业机密的名义坚持使用专有固件或驱动。</p><p>这样必然会引起潜在用户的批评，但是开源硬件制造者没得选，只能折中他们的愿景。寻找其他生产商也不能解决问题，有一个原因是这样做意味着更多延迟，但是更多的是因为完全免授权费的硬件是不存在的。像三星这样的业内巨头对免费硬件没有任何兴趣，而作为新人，开源硬件制造者也没有影响力去要求什么。</p><p>更何况，就算有免费硬件，生产商也不能保证会用在下一批生产中。制造者们会轻易地发现他们每次需要生产的时候都要重打一次一模一样的仗。</p><p>这些都还不够，这个时候开源硬件制造者们也许已经花了6-12个月时间来讨价还价。等机会终于来了，产业标准却已经变更，于是他们可能为了升级产品规格又要从头来过。</p><h3 id="短暂而且残忍的货架期" tabindex="-1">短暂而且残忍的货架期 <a class="header-anchor" href="#短暂而且残忍的货架期" aria-label="Permalink to “短暂而且残忍的货架期”">​</a></h3><p>尽管面对这么多困难，一定程度上开放的硬件也终于推出了。还记得寻找生产商时的挑战吗？对于分销商也会有同样的问题 -- 还不只是一次，而是每个地区都要解决。</p><p>通常，分销商和生成商一样保守，对于和新人或新点子打交道也很谨慎。就算他们同意一个产品上架，他们也轻易能够决定不鼓励自己的销售代表们做推广，这意味着这个产品会在几个月后很有效率地下架。</p><p>当然，在线销售也是可以的。但是同时，硬件还是需要被存放在某个地方，这也会增加成本。而按需生产就算可能的话也将非常昂贵，而且没有组装的元件也需要存放。</p><h3 id="衡量整件怪事" tabindex="-1">衡量整件怪事 <a class="header-anchor" href="#衡量整件怪事" aria-label="Permalink to “衡量整件怪事”">​</a></h3><p>在这里我只是粗略地概括了一下，但是任何涉足过制造的人会认同我形容为行业标准的东西。而更糟糕的是，开源硬件制造者们通常只有在亲身经历过后才会有所觉悟。不可避免，他们也会犯错，从而带来更多的延迟。</p><p>但重点是，一旦你对整个过程有所了解，你对另一个开源硬件进行尝试的新闻的反应就会改变。这个过程意味着，除非哪家公司处于严格的保密模式，对于产品将于六个月内发布的声明会很快会被证实是过期的推测。很可能是12-18个月，而且面对之前提过的那些困难很可能意味着这个产品永远都不会真正发布。</p><p>举个例子，就像我写的，人们等待第一代Steam Machines面世，它是一台基于Linux的游戏主机。他们相信Steam Machines能彻底改变Linux和游戏。</p><p>作为一个市场分类，Steam Machines也许比其他新产品更有优势，因为参与开发的人员至少有开发软件产品的经验。然而，整整一年过去了Steam Machines的开发成果都还只有原型机，而且直到2015年中都不一定能买到。面对硬件生产的实际情况，就算有一半能见到阳光都是很幸运了。而实际上，能发布2-4台也许更实际。</p><p>我做出这个预测并没有考虑个体努力。但是，对硬件生产的理解，比起那些Linux和游戏的黄金年代之类的预言，我估计这个更靠谱。如果我错了也会很开心，但是事实不会改变：让人吃惊的不是如此多的Linux相关硬件产品失败了，而是那些虽然短暂但却成功的产品。</p><hr>',28)),i("p",null,[a[1]||(a[1]=t("via: ",-1)),n(e,{href:"http://www.datamation.com/open-source/what-linux-users-should-know-about-open-hardware-1.html"},{default:o(()=>[...a[0]||(a[0]=[t("http://www.datamation.com/open-source/what-linux-users-should-know-about-open-hardware-1.html",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=t("作者：",-1)),n(e,{href:"http://www.datamation.com/author/Bruce-Byfield-6030.html"},{default:o(()=>[...a[2]||(a[2]=[t("Bruce Byfield",-1)])]),_:1}),a[6]||(a[6]=t(" 译者：",-1)),n(e,{href:"https://github.com/zpl1025"},{default:o(()=>[...a[3]||(a[3]=[t("zpl1025",-1)])]),_:1}),a[7]||(a[7]=t(" 校对：",-1)),n(e,{href:"https://github.com/tinyeyeser"},{default:o(()=>[...a[4]||(a[4]=[t("Mr小眼儿",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...a[9]||(a[9]=[t("Linux中国",-1)])]),_:1}),a[12]||(a[12]=t(" 荣誉推出",-1))])])}const S=r(d,[["render",h]]);export{C as __pageData,S as default};
